"""Convert decimal number to binary number by iteration.

    Time complexity: O(d/2).
    Space complexity: O(d/2).
    """
def decimal_to_base2(dec: Any) -> object {
    rem_stack = [];
    while (dec > 0) {
        (dec, rem) = divmod(dec, 2);
        rem_stack.append(rem);
    }
    bin_num = '';
    while rem_stack {
        bin_num += str(rem_stack.pop());
    }
    return bin_num;
}

"""
    In this algorithm, we want to find whether element x belongs to a set of numbers stored in an array numbers[]. Where l and r represent the left and right index of a sub-array in which searching operation should be performed.

    """
def maf_binary(sorted_array: Any, value: Any) -> object {
    err = "Not Found";
    min = 0;
    max = len(sorted_array) - 1;
    while (min <= max) {
        mid = (min + max) // 2;
        if (sorted_array[mid] > value) {
            max = mid - 1;
        } elif (sorted_array[mid] < value) {
            min = mid + 1;
        } else {
            return mid;
        }
    }
}

