"""
    Set bit to at the given offset to 1
    """
def set_bit(num: Any, offset: Any) -> object {
    mask = 1 << offset;
    return (num | mask);
}

"""Copy ``template`` and interpolate a repository ID into its ``_href``."""
def _customize_template(template: Any, repository_id: Any) -> object {
    template = template.copy();
    template['_href'] = template['_href'].format(repository_id);
    return template;
}

